python3 -c "import re, os; total=0
for root, dirs, files in os.walk('frontend/src'):
    for f in files:
        if not f.endswith(('.tsx','.ts')): continue
        p=os.path.join(root,f)
        if 'i18n' in p or 'I18nProvider' in p: continue
        try: content=open(p).read()
        except: continue
        for l in content.split('\n'):
            if re.search(r'[\u4e00-\u9fff]', l) and not l.strip().startswith(('//','*','/*','<!--')):
                total+=1
                print(f'{p}: {l.strip()[:80]}')
assert total == 0, f'expected 0 hard-coded zh-CN literals, found {total}'"
